INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(4100, 0, 41, 0, 0, 0, 'Deadwind Pass', 'Between the dark woods of Duskwood and the Swamp of Sorrows lies a stretch of land with no life left in it. Its trees stand as grey, withered husks, its soil is ash, and carrion birds called sky shadows circle above the ravines. Travelers from Darkshire who must carry goods east toward the Blasted Lands take this road, and few do so gladly. At the heart of the pass rises Karazhan, the tower of Medivh, the Last Guardian. When Medivh fell, slain within those walls by Anduin Lothar and the young mage Khadgar, a curse settled over the tower and the country around it, and it has never lifted. Ghosts wander the tower grounds, the ruined village to its south and the old churchyard nearby. In the southern hills, the Deadwind ogres have dug their mounds into the cliffs of the Vice. Outside the tower gate, mages of the Violet Eye keep their long watch on behalf of Dalaran.', 'warcraft.wiki.gg/wiki/Deadwind_Pass (devoid of life, withered husks, curse over tower and lands, ogres in the Vice, Violet Eye study the tower); warcraft.wiki.gg/wiki/Medivh (slain by Lothar and Khadgar, death cursed the tower and surrounding area); quest 1395 description (route from Darkshire east through Deadwind Pass); quest 9680 description (the ashes of Deadwind Pass); quest 9826 description (Violet Eye agents of the Kirin Tor); DB spawns: Sky Shadow 7376, Deadwind ogres in area 2561, ghosts around Karazhan, Alturus and Leryda at the gate'),
(4101, 1, 41, 1, 0, 0, 'Deadman''s Crossing', 'Deadman''s Crossing is the crossroads where the road through the pass divides, one way leading back toward Duskwood, another on to the Swamp of Sorrows, and a third turning south toward Karazhan. The welcome it offers is grim. A hangman''s tree stands at the junction with a pair of corpses still hanging from it, and the signposts beside the road bear no distances, only warnings: Turn Back, and Abandon hope, all ye who enter here. Those who keep to the road and press on quickly are seldom troubled. Those who stray from it may not return.', 'warcraft.wiki.gg/wiki/Deadman%27s_Crossing (crossroads to Duskwood, Swamp of Sorrows and Karazhan; hangman''s tree with corpses; signs); DB gameobjects 177185 and 177186 (sign texts) at -10451,-1721, posarea 2697'),
(4102, 1, 41, 2, 0, 0, 'Deadwind Ravine', 'Deadwind Ravine is a craggy cleft that cuts through the mountains of the pass, running south toward Karazhan. The western road from Duskwood follows its upper level, so that travelers look down into a gulf of bare stone and dead timber, and at its far end a bridge carries the way on toward the tower. Nothing grows here, and little lives. The sky shadows, the great carrion birds of the pass, wheel above the ravine, watching for whatever falls by the wayside.', 'warcraft.wiki.gg/wiki/Deadwind_Ravine (craggy cleft running south toward Karazhan, western road on the upper level); warcraft.wiki.gg/wiki/Sky_Shadow (vulture, carrion bird, uses Rend); DB: 9 Sky Shadow 7376 spawns in area 2558; warcraft.wiki.gg/wiki/Deadwind_Ravine (southern bridge near the tower at the end of the area)'),
(4103, 1, 41, 3, 0, 0, 'Ariden''s Camp', 'Just north of the main road that runs between Duskwood and the Swamp of Sorrows lies Ariden''s Camp, a deserted campsite in the hills of the pass. A campfire still burns there, yet no one is ever found tending it. The camp carries the name of a man called Ariden, but no one passing through Deadwind Pass seems to know who he was, what business brought him to these hills so near Medivh''s tower, or where he has gone.', 'warcraft.wiki.gg/wiki/Ariden%27s_Camp (deserted campsite north of the main road between Duskwood and Swamp of Sorrows); DB gameobject 176464 Campfire at -10436,-2140, posarea 2560; DB gameobject_template 176464 (type 8 spell focus 4, campfire display 192: a lit cooking fire); no creatures spawn in area 2560'),
(4104, 1, 41, 4, 0, 0, 'Sleeping Gorge', 'The Sleeping Gorge is a small chasm in the eastern part of Deadwind Pass. One of the paths south toward Karazhan runs along its floor for a stretch before it turns east into the Vice, the ogre country of the southern hills. Like the rest of the pass, the gorge is a lifeless place of bare rock and withered trees, and the only things that stir in it are the sky shadows, circling above in search of carrion.', 'warcraft.wiki.gg/wiki/Sleeping_Gorge (small chasm in eastern Deadwind Pass, a path south to Karazhan runs through it before turning east into the Vice); DB: Sky Shadow 7376 spawns in area 2938'),
(4105, 1, 41, 5, 0, 0, 'The Vice', 'The Vice is the southern hill country of Deadwind Pass, along the road that leads to Karazhan, and it belongs to the Deadwind ogres. Their mounds are dug into the slopes, and their camps are marked by bonfires and great cooking cauldrons. Brutes and ogre mages hold the open ground, while maulers and warlocks keep to the caves farther south. Why the ogres chose to settle in so desolate a place, so close to a cursed tower, no one knows. Ghosts from Karazhan''s grounds drift into their territory as well.', 'warcraft.wiki.gg/wiki/The_Vice (southern Deadwind Pass along the road to Karazhan, home of the Deadwind ogres, mounds and camps, no one knows why they settled); DB spawns in area 2561: Deadwind Brute 7369, Ogre Mage 7379, Mauler 7371, Warlock 7372; ghosts 12377, 12378, 7370, 12379, 12380; DB gameobjects 176558, 176560 Bonfire and 176559, 176574 Cauldron in 2561'),
(4106, 1, 41, 6, 0, 0, 'Grosh''gok Compound', 'Grosh''gok Compound is the largest of the ogre mounds in the Vice and the southernmost of its caves, burrowed deep into the hills. It is the chief stronghold of the Deadwind ogres. The clan''s hulking maulers and its warlocks, seldom seen on the open slopes where the brutes and ogre mages roam, are found in the caves of the southern Vice. Who leads the clan, and what purpose holds the ogres in the dead lands of the pass, remains unknown to outsiders.', 'warcraft.wiki.gg/wiki/Grosh%27gok_Compound (ogre mound in the Vice, southernmost and largest of the caves); warcraft.wiki.gg/wiki/Deadwind_ogre (Grosh''gok Compound is their base, leader unknown); DB spawns: Deadwind Warlock 7372 and Mauler 7371 at x -11080..-11162, y -2367..-2487, the southern cave'),
(4107, 1, 41, 7, 0, 0, 'Karazhan', 'Karazhan rises at the heart of Deadwind Pass, the tower of Medivh, the Last Guardian. The mages of Dalaran say it is more than a building: trace the ley lines of Azeroth and they all converge on a point beneath it, and some call the tower a portal into the nether, a beacon shining into other worlds. It was not always so ominous. The darkness came with Medivh''s death. Since then the tower has sealed its doors to the world, its grounds have filled with wailing spectres and the restless dead of its old household, and agents of the Violet Eye wait at the gate for a way back inside.', 'npc_text 9242 (Alturus: ley lines converge below the tower); npc_text 10546 (Leryda: Karazhan was not always so ominous, darkening came with Medivh''s death); quest 9844 description (portal into the nether, beacon into other worlds); quest 9829 description (Karazhan sealed itself off); quest 9825 description (outside of Karazhan crawling with ghostly beings); DB spawns in 2562: Wailing Spectre, Damned Soul, Restless Shade, Unliving Caretaker, Unliving Resident; Alturus, Leryda, Darius at the gatehouse'),
(4108, 1, 41, 8, 0, 0, 'Morgan''s Plot', 'Not far from Karazhan stands Morgan''s Plot: a small, decrepit church with its graveyard and crypt. In better days a human village and its church grew up around the tower, and both were abandoned long ago. The dead have not left with the living. Restless shades and wailing spectres drift among the headstones, unliving residents still haunt the old chapel, and a spirit healer keeps silent watch over the graves.', 'warcraft.wiki.gg/wiki/Morgan%27s_Plot (small decrepit church with graveyard and crypt behind Karazhan, Unliving Residents in the chapel, spirit healer); warcraft.wiki.gg/wiki/Deadwind_Pass (human village and its church grew around the tower, both abandoned); DB spawns in 2563: Restless Shade 7370, Wailing Spectre 12377, Spirit Healer 6491, Gate 177203; DB: Unliving Resident 12380 spawns beside the chapel pews (gameobject 160866) at -11180,-1855'),
(4109, 1, 41, 9, 0, 0, 'The Master''s Cellar', 'South of Karazhan, beneath the ruins of a small village that may once have housed the tower''s servants, lies the Master''s Cellar. Its two entrances lead down into a great wine cellar and a second vault whose floor has collapsed into natural caves below. Both are riddled with ghosts: unliving residents and caretakers still linger among the casks, while damned souls and wailing spectres drift through the dark. Somewhere below lie an underground pond and a well, and Archmage Alturus holds that near such hidden water his scrying crystal can read the tower''s energies far more clearly.', 'warcraft.wiki.gg/wiki/The_Master%27s_Cellar (pre-Cataclysm: south of Karazhan, beneath village ruins likely home of the servants, wine cellar, collapsed floor into caves, undead types); quest 9824 description (underground pond and well in a cellar below, crystal would pick up signals near underground water); DB: Underground Well Credit Marker 18161 and Underground Pond Credit Marker 18162, gameobject 182187 Underground Water Source Focus'),
(4110, 2, 41, 1, 0, 0, 'Medivh', 'Medivh, son of the Guardian Aegwynn, was the Last Guardian of Tirisfal and master of Karazhan. From before his birth the spirit of the demon lord Sargeras lay hidden within him, and over the years it twisted his mind until he made a pact with the warlock Gul''dan and helped open the Dark Portal for the orcish Horde. His boyhood friend Anduin Lothar and his own apprentice Khadgar stormed the tower and struck him down. His death cast the curse that still hangs over Karazhan and the pass. Yet the Violet Eye speak of it carefully, as what they believe was his death, for tales tell of a prophet who walked Azeroth years later.', 'warcraft.wiki.gg/wiki/Medivh (son of Aegwynn, Sargeras within him before birth, pact with Gul''dan, opened the Dark Portal, raised alongside Lothar, slain by Lothar and Khadgar, death cursed the tower, returned as the Prophet in Warcraft III); npc_text 10546 (Leryda: what we believe was Medivh''s death); quest 9630 description (Violet Eye seek Medivh''s journal); quest 9645 The Master''s Terrace (Kamsis 16815: Medivh''s journal holds his memories)'),
(4111, 2, 41, 2, 0, 0, 'Archmage Alturus', 'Archmage Alturus is a senior agent of the Violet Eye, a secret sect of Dalaran''s Kirin Tor charged long ago with watching over Karazhan and its master, lest Medivh''s power run out of control, which in time it did. Now an old man, he keeps his post at the tower gate with Archmage Leryda and his apprentice, Darius, measuring the tower''s energies and studying the ghosts that haunt its grounds. Alturus is curious, exacting and impatient with mysteries: The tower holds many secrets, and he intends to lay every one of them bare. He believes every ley line in Azeroth meets beneath the tower.', 'quest 9826 description (Violet Eye agents of the Kirin Tor watching Karazhan and Medivh, in case things got out of hand); quest 9824 description (someone my age); quest 9825 description (unknowns bother me; Karazhan has many secrets, determined to uncover all of them); npc_text 9242 (ley lines converge beneath the tower); quest 11216 description (Tasserel sends adventurers to Alturus); warcraft.wiki.gg/wiki/Archmage_Alturus (high-ranking Violet Eye, reports to Cedric, serious and exacting, apprentice Darius); DB spawns: Alturus 17613, Leryda 18253, Apprentice Darius 18255 together at the gate'),
(4112, 2, 41, 3, 0, 0, 'Archmage Leryda', 'Archmage Leryda is a high elf mage of the Violet Eye who waits beside Archmage Alturus at the gates of Karazhan. Where her colleague is absorbed in readings and theories, Leryda speaks of the tower''s past and of the day it changed: Karazhan, she says, was not always so ominous, and its darkening came only with the death of Medivh, or what the Eye believes was his death. To those who have proven themselves in the Eye''s service she grants the Violet Signet, a ring that grows in power as its bearer''s loyalty is shown, shaped to whichever path its wearer chooses.', 'warcraft.wiki.gg/wiki/Archmage_Leryda (high elf mage, Violet Eye, waits at the entrance with Alturus and Darius); npc_text 10546; quests 10729-10732 (Path of the Violet Mage, Restorer, Assassin, Protector), 10733, 10738, 10725 descriptions and reward texts (signet grows in power), 11031 (changing paths); creature_queststarter: Leryda 18253 starts the signet quests'),
(4113, 3, 41, 1, 0, 0, 'The Watchers at the Gate', 'After the Dark Portal opened anew, the Violet Eye sent word from the gates of Karazhan seeking capable allies. Archmage Alturus asked them to carry his scrying crystal down to the pond and the well in the cellar below the tower, and to gather the essence of the ghosts that crowd its grounds. The readings alarmed him. Karazhan, which should pour out arcane currents, had become a vast void, silent but for one faint demonic echo. His report went to Archmage Cedric outside Dalaran and from there to Khadgar, Medivh''s old apprentice and one of the few who could open the sealed tower. With a key restored at last, the Eye sought the coded log of its slain spy Keanna, whose final entries told of a Burning Legion agent arriving at the top of the tower. That intruder had to be destroyed, and only the keyholder could reach it.', 'quests 11216, 9824, 9825, 9826, 9829, 9838, 9840, 9843, 9844, 9860 (descriptions and reward texts); quest 9829 description (only Khadgar and Medivh could reopen Karazhan); quest_template_addon: 9824 and 9825 lead to 9826; 9838 to 9860 chain; creature_queststarter: Tasserel 23948 starts 11216; Alturus starts 9824, 9825, 9826'),
(4114, 3, 41, 2, 0, 0, 'The Bones of Arcanagos', 'Long ago the blue dragon Arcanagos came to Karazhan to confront Medivh and was struck down by the tower''s master. Burned by Medivh''s magic, he fell in the mountains of Deadwind Pass, and only blackened bone remained. The Violet Eye learned more of that battle through Medivh''s own journal, recovered from the tower after their agents sent to find it had vanished. The journal keeps more than words: it holds Medivh''s memories, and on the Master''s Terrace it showed the fight itself. Alturus reasoned that if Medivh had woven his own essence into the spell that slew the dragon, a residue of it might linger in the remains. The search turned to the mountains south of the tower, where a charred fragment of draconic bone, still teeming with energy, was found among the ashes. Yet the residue proved as lifeless as the dragon himself, and to use it Alturus would have to raise Arcanagos from his bones, risking a terror called Nightbane.', 'quests 9630, 9645, 9680, 9631, 9644 (descriptions and reward texts); warcraft.wiki.gg/wiki/Arcanagos (blue dragon, confronted Medivh, burned from within, died in the mountains of Deadwind Pass, returned as Nightbane); DB gameobject 181963 Charred Bone Fragment at -11182,-1958; quest 9631 description (residue devoid of life like Arcanagos), 9644 description (raising the remains risks Nightbane)');
